    return {
        list: function() {
            return Object.keys(definitions)
                .filter((k) => definitions[k].label)
                .map((k) => ({ id: k, label: definitions[k].label }));
        },
        getAvailableNames: function() {
            return Object.keys(definitions);
        },
        getTable: function(name) {
            return definitions[name] ? definitions[name].packed : definitions['viridis'].packed;
        },
        /** [r, g, b] for a table entry, unpacked from the ABGR word. */
        getRgb: function(name, index) {
            const def = definitions[name] || definitions['viridis'];
            const idx = Math.max(0, Math.min(255, Math.floor(index)));
            const p = def.packed[idx];
            return [p & 255, (p >>> 8) & 255, (p >>> 16) & 255];
        }
    };
